const SL_ADV_BANK=[
 {"id":"slbA0","w":"Шкала звучности: гласные — 4, сонорные — 3, звонкие шумные — 2, глухие шумные — 1. Какой профиль у слова «рыба»?","a":"3–4–2–4","why":"Звуки [р] — сонорный (3), [ы] — гласный (4), [б] — звонкий шумный (2), [а] — гласный (4). Порядок звуков по звучности, а не цифры, определяет, где гребни и впадины.","l":1,"opts":["3–4–2–4","3–4–1–4","2–4–2–4","4–3–2–4"],"q":"Профиль слова"},
 {"id":"slbA1","w":"Звук [с] в слове «сад» неслоговой, а в «кс-кс-кс» слоговой. Что это показывает?","a":"слоговость зависит от положения звука среди соседей","why":"Слоговым становится звук, который звучнее соседей или окружён паузами; один и тот же звук в разных окружениях ведёт себя по-разному.","l":1,"opts":["слоговость зависит от положения звука среди соседей","в «кс-кс-кс» звук [с] произносится громче, чем в слове «сад», и поэтому образует слог","в «кс-кс-кс» на письме пропущена гласная, которую произносят","слоговыми бывают только шумные согласные в междометиях"],"q":"Одно и то же [с]"},
 {"id":"slbA2","w":"Сколько слогов в строке «К нам в окошко застучит»?","a":"7","why":"Слоги дают нам (1), о-кош-ко (3), за-сту-чит (3); предлоги «к» и «в» гласной не содержат и слога не образуют.","l":1,"opts":["5","7","8","9"],"q":"Счёт слогов в строке"},
 {"id":"slbA3","w":"У слова «лампа» профиль по одной шкале 3–4–3–1–4, по другой 2–3–2–1–3. Какой вывод верен?","a":"слоги и места впадин от шкалы не зависят: важен порядок звуков","why":"Числа условны. Гребни стоят на гласных, впадина — на [п] в обеих шкалах, потому что порядок «гласные — сонорные — шумные» один.","l":1,"opts":["слоги и места впадин от шкалы не зависят: важен порядок звуков","верна только четырёхступенчатая шкала, а вторая даёт ошибочное число слогов","по второй шкале слов с тремя звуками больше, поэтому слогов тоже больше","шкала применима только к гласным, а согласные в профиль не входят"],"q":"Две шкалы"},
 {"id":"slbA4","w":"Что называют тактом в теории Белошапковой?","a":"группу слогов, объединённую одним ударением","why":"Такт — группа слогов вокруг одного ударного: предлог без гласной входит в такт соседнего слова («в-устах-её»).","l":1,"opts":["группу слогов, объединённую одним ударением","паузу между двумя соседними слогами в строке","слог, который произносится сильнее остальных","группу слов, записанную в одной строке стиха"],"q":"Такт"},
 {"id":"slbA5","w":"В междометии «брр» нет гласной. Какой звук по теории звучности может стать слоговым?","a":"сонорный [р]","why":"Самый звучный звук слова — сонорный [р]; сонорные могут быть слоговыми (редко, в беглой речи).","l":1,"opts":["сонорный [р]","шумный [б]","гласный, пропущенный на письме","слоговых звуков нет совсем"],"q":"Слоговой звук в «брр»"},
 {"id":"slbA6","w":"Гласные — 3, сонорные — 2, шумные — 1. Какой профиль у слова «парта»?","a":"1–3–2–1–3","why":"[п] шумный (1), [а] гласный (3), [р] сонорный (2), [т] шумный (1), [а] гласный (3).","l":2,"opts":["1–3–2–1–3","1–3–1–2–3","2–3–2–1–3","1–3–2–2–3"],"q":"Профиль слова"},
 {"id":"slbA7","w":"Где проходит слогораздел в слове «парта» и на чём это основано?","a":"после [р], перед [т]: звучность падает, и слогораздел стоит перед минимумом","why":"Закон восходящей звучности: слог растёт от тихого к громкому; слогораздел — перед самым тихим звуком после падения.","l":2,"opts":["после [р], перед [т]: звучность падает, и слогораздел стоит перед минимумом","перед [р], потому что согласный всегда уходит к следующему гласному","после первого [а], потому что слог должен кончаться гласным","слово «парта» вообще не делится: в нём два согласных подряд"],"q":"Где слогораздел"},
 {"id":"slbA8","w":"В каком слове звучность внутри начального слога падает, не дойдя до гласного?","a":"мглой","why":"В слове «мглой» профиль начального слога 2–1–2–3: после [м] звучность падает к [г]. В словах «стужа» (1–1–3), «ноги» (2–3), «прикосновение» (1–2–3) такого падения нет.","l":2,"opts":["мглой","стужа","ноги","прикосновение"],"q":"Начало слова"},
 {"id":"slbA9","w":"Что объединяет законы 2–4 у Белошапковой?","a":"слогораздел проходит там, где контраст соседних звуков по сонорности наибольший","why":"Это общая формулировка законов 2–4; закон 5 (долгие согласные) требует обратного — наименьшего контраста.","l":2,"opts":["слогораздел проходит там, где контраст соседних звуков по сонорности наибольший","слогораздел всегда проходит сразу после гласного, чтобы слог оставался открытым","слогораздел совпадает со стыком значимых частей слова","слогораздел проходит перед каждым сонорным"],"q":"Законы 2–4"},
 {"id":"slbA10","w":"Почему деление слов «волна» и «карман» на слоги нельзя назвать единственным?","a":"между двумя сонорными допустимы оба деления","why":"В «Русской грамматике» (1980) допущены оба деления: ка-рман и кар-ман.","l":2,"opts":["между двумя сонорными допустимы оба деления","эти слова образованы с приставкой","в них слогораздел проходит внутри гласного","это слова иноязычного происхождения"],"q":"Спорные слова"},
 {"id":"slbA11","w":"Принцип Тредиаковского, понятый буквально, даёт для слова «карта» деление ка-рта. Почему?","a":"слова начинаются с [рт] (ртуть), значит, и слог может так начинаться","why":"Принцип: согласные, начинающие слово, начинают и слог внутри слова; а закон звучности даёт кар-та — отсюда расхождение.","l":2,"opts":["слова начинаются с [рт] (ртуть), значит, и слог может так начинаться","сонорный [р] всегда уходит к следующему гласному","в слове «карта» два сонорных звука подряд","на стыке приставки и корня слогораздел может стоять где угодно"],"q":"Принцип Тредиаковского"},
 {"id":"slbA12","w":"Как слогораздел по закону 5 Белошапковой делит долгий (двойной) согласный между гласными, например в слове «конный»?","a":"пополам: слогораздел там, где контраст наименьший","why":"Закон 5 (Белошапкова): [кон-ный]; исключения — долгие [ш':] и [ж':].","l":2,"opts":["пополам: слогораздел там, где контраст наименьший","перед всем долгим звуком: он уходит к следующему гласному","после всего долгого звука: он остаётся в предыдущем слоге","долгий согласный слогораздела внутри себя не допускает"],"q":"Долгий согласный"},
 {"id":"slbA13","w":"Для слова «район» по слогам получается ра-йон, а допустим только рай-он. Что решает?","a":"запрет отделять й от гласной сильнее деления на слоги","why":"§ 214 запрещает отрывать й от предшествующей гласной; слоговой принцип уступает запрету.","l":3,"opts":["запрет отделять й от гласной сильнее деления на слоги","слоги в слове определены неверно: слогораздел стоит после й","перенос обязан совпадать со слогораздельным делением","буква й в этом слове обозначает гласный звук"],"q":"Слог или запрет"},
 {"id":"slbA14","w":"Параграф 211 запрещает «а-кация», хотя «а» образует слог. Как это понимать?","a":"запрет относится к письму и читаемости, а не к звукам","why":"Единица строки — буква: одну букву нельзя оставить или перенести, даже если она слог.","l":3,"opts":["запрет относится к письму и читаемости, а не к звукам","«а» в начале слова слога не образует","слоги из одной гласной буквы фонетика не признаёт","перенос обязан совпадать со стыком морфем"],"q":"Запрет письма"},
 {"id":"slbA15","w":"Чем объясняют запрет отделять согласную от следующей гласной?","a":"слоговым принципом графики: гласная показывает твёрдость или мягкость согласной","why":"Буква «б» в словах «быть» и «бить» обозначает и твёрдый, и мягкий звук; узнать, какой, можно по следующей гласной.","l":3,"opts":["слоговым принципом графики: гласная показывает твёрдость или мягкость согласной","звонкостью согласной: перед гласной звонкие согласные произносятся иначе, чем глухие","тем, что гласная в таком слоге всегда ударная","правилом о переносе ь и ъ"],"q":"Основание запрета"},
 {"id":"slbA16","w":"В § 215 есть примеры «ша-лун, чу-дак». Что они показывают?","a":"запрет действует и там, где гласная не показывает мягкость согласной","why":"После [ш] и [ч'] твёрдость и мягкость заложены в самих согласных, но запрет всё равно действует: он шире графического основания.","l":3,"opts":["запрет действует и там, где гласная не показывает мягкость согласной","после шипящих согласную от гласной оторвать можно: там гласная ничего не обозначает","слоговой принцип графики здесь вообще не применяется","эти слова переносятся только после приставки"],"q":"Пример из § 215"},
 {"id":"slbA17","w":"Слово «Азия» трёхсложное, но не переносится. Почему?","a":"каждое из мест переноса нарушает хотя бы один запрет","why":"А-зия оставляет одну букву, аз-ия отрывает з от и, ази-я переносит одну букву.","l":3,"opts":["каждое из мест переноса нарушает хотя бы один запрет","в слове есть буква я, образующая два звука","слова с тремя слогами переносят только по приставке","в слове нет согласных, которые можно разделить"],"q":"Азия"},
 {"id":"slbA18","w":"Какие места переноса в слове можно не проверять запретами о длине частей, потому что они отпадают сразу?","a":"места между согласной и следующей гласной","why":"Такие места запрещены § 215; на остальных проверяются § 211–212 и правила о ь, ъ, й.","l":3,"opts":["места между согласной и следующей гласной","места между гласной и следующей согласной","места между двумя согласными","места между двумя гласными"],"q":"Без перебора"},
 {"id":"slbA19","w":"Сколько вариантов переноса даёт группа согласных в слове «детство» (слева от группы больше одной буквы)?","a":"4","why":"Между гласными четыре согласные буквы [т, с, т, в]: на строке может остаться 0, 1, 2 или 3 буквы группы, четыре варианта.","l":4,"opts":["3","4","5","2"],"q":"Число вариантов"},
 {"id":"slbA20","w":"Параграф 217 разрешает разбивать группу неодинаковых согласных любым образом. Что всё же ограничивает выбор места переноса?","a":"запреты § 211 и § 215: одна буква на строке, согласная без своей гласной","why":"«Любым образом» — внутри допустимых мест: нельзя оставить одну букву (о-стров) и отделить согласную от следующей гласной (сестр-а).","l":4,"opts":["запреты § 211 и § 215: одна буква на строке, согласная без своей гласной","только ударение: перенос возможен лишь после ударного слога","только число слогов: перенос обязан совпасть с границей слога","ничто не ограничивает: все места между буквами допустимы"],"q":"Что ограничивает выбор"},
 {"id":"slbA21","w":"В слове «войско» группа «йск». Сколько вариантов переноса внутри группы?","a":"два: вой-ско и войс-ко","why":"По § 214 й остаётся на строке со своей гласной; остальные согласные группы разбиваются по § 217: после й и после с.","l":4,"opts":["два: вой-ско и войс-ко","один: вой-ско","три: во-йско, вой-ско, войс-ко","ни одного: слово не переносится"],"q":"Группа с й"},
 {"id":"slbA22","w":"К какой части слова относятся двойные буквы в слове «русский»?","a":"к стыку корня и суффикса","why":"§ 216 называет два случая: двойные в корне (масса) и на стыке корня и суффикса (рус-ский, кон-ный).","l":4,"opts":["к стыку корня и суффикса","к корню","к стыку приставки и корня","к окончанию"],"q":"Двойные буквы"},
 {"id":"slbA23","w":"Какой перенос прямо запрещён § 213 Правил (2006)?","a":"бул-ьон","why":"Параграф запрещает отделять ь и ъ от предшествующей согласной; примеры: буль-он верно, бул-ьон недопустимо.","l":4,"opts":["бул-ьон","бу-льон","буль-он","бульо-н"],"q":"Что запрещает § 213"},
 {"id":"slbA24","w":"Почему в заданиях курса слово «коньки» переносят только как конь-ки?","a":"так принято в курсе: § 213 запрещает лишь отрыв ь от согласной","why":"§ 213 запрещает отделять ь от предшествующей согласной; перенос ко-ньки им прямо не назван, но курс засчитывает только перенос после ь.","l":4,"opts":["так принято в курсе: § 213 запрещает лишь отрыв ь от согласной","§ 213 прямо запрещает перенос ко-ньки","после слога «ко» в слове нет допустимого места","буква ь вообще нельзя переносить на другую строку"],"q":"Практика курса"},
 {"id":"slbA25","w":"Что сказано в § 216 о двойных согласных после приставки?","a":"они могут не разбиваться: со-жжённый и сож-жённый","why":"Правило о разделении двойных относится к корню и стыку корня и суффикса; после приставки допустимы оба переноса.","l":4,"opts":["они могут не разбиваться: со-жжённый и сож-жённый","они обязательно разбиваются, как в корне","они не разбиваются никогда","они разбиваются только в сложных словах"],"q":"После приставки"},
 {"id":"slbA26","w":"Слово «лампа»: слоги лам-па, переносы ла-мпа и лам-па. Каково отношение?","a":"переносов больше, чем границ слогов","why":"Группа «мп» разных согласных разбивается любым образом (§ 217), поэтому мест переноса больше.","l":5,"opts":["переносов больше, чем границ слогов","границы совпадают","переносов меньше, чем границ слогов","границы стоят в разных местах"],"q":"Слог и перенос"},
 {"id":"slbA27","w":"Слово «акула»: слоги а-ку-ла, перенос аку-ла. Каково отношение?","a":"переносов меньше, чем границ слогов","why":"Граница после первой буквы оставила бы одну букву на строке (§ 211).","l":5,"opts":["переносов меньше, чем границ слогов","границы совпадают","переносов больше, чем границ слогов","границы стоят в разных местах"],"q":"Слог и перенос"},
 {"id":"slbA28","w":"Слово «майор»: слоги ма-йор, перенос май-ор. Каково отношение?","a":"границы стоят в разных местах","why":"§ 214: й нельзя отделять от предшествующей гласной, поэтому место переноса стоит после й, а граница слога — перед ней.","l":5,"opts":["границы стоят в разных местах","границы совпадают","переносов больше, чем границ слогов","переносов нет"],"q":"Слог и перенос"},
 {"id":"slbA29","w":"Слово «нововведение» переносят только по частям: ново-введение. К какому положению относится это правило?","a":"стык частей сложного слова: единственный вариант","why":"§ 218: на стыке частей сложного слова возможны только переносы по значимым частям.","l":5,"opts":["стык частей сложного слова: единственный вариант","корень: любой вариант","стык приставки и корня: предпочтительный вариант","суффикс: любой вариант"],"q":"Степень свободы"},
 {"id":"slbA30","w":"Чем объясняется расхождение слога и переноса в слове «район»?","a":"запретом § 214: й не отделяют от предшествующей гласной","why":"По звукам [ра-й'он], но на письме й остаётся с гласной: рай-он.","l":5,"opts":["запретом § 214: й не отделяют от предшествующей гласной","запретом § 211: на строке остаётся одна буква","правилом § 217 о группе разных согласных","правилом § 216 о двойных согласных"],"q":"Причина расхождения"},
 {"id":"slbA31","w":"Какая закономерность связывает состав слова и свободу переноса?","a":"чем сложнее слово по составу, тем теснее перенос привязан к границам частей","why":"Корень — свобода, стык приставки — предпочтение, стык частей сложного слова — единственный вариант.","l":5,"opts":["чем сложнее слово по составу, тем теснее перенос привязан к границам частей","чем длиннее слово, тем больше в нём мест переноса и тем свободнее они выбираются","чем больше в слове гласных, тем свободнее перенос","перенос зависит только от ударения"],"q":"Закономерность"}
];

